import React, { useEffect, useState } from 'react';
import { Root, View, Panel, PanelHeader, Spinner, Div } from '@vkontakte/vkui';
import { initVK, getUserInfo } from './vk';
import PublicTournamentView from './tabs/PublicTournamentView';

const App = () => {
  const [user, setUser] = useState<Record<string, any> | null>(null);
  const [loading, setLoading] = useState(true);
  const [isGuest, setIsGuest] = useState(false);

  useEffect(() => {
    initVK();
    getUserInfo()
      .then((userData: Record<string, any>) => {
        setUser(userData);
        setIsGuest(false);
      })
      .catch(() => {
        setIsGuest(true);
      })
      .finally(() => {
        setLoading(false);
      });
  }, []);

  if (loading) {
    return (
      <Root activeView="loading">
        <View id="loading" activePanel="loading">
          <Panel id="loading">
            <PanelHeader>Загрузка...</PanelHeader>
            <Div style={{ display: 'flex', justifyContent: 'center', padding: '20px' }}>
              <Spinner size="medium" />
            </Div>
          </Panel>
        </View>
      </Root>
    );
  }

  return (
    <Root activeView="main">
      <View id="main" activePanel="main">
        <Panel id="main">
          {isGuest ? (
            <PublicTournamentView />
          ) : (
            <PublicTournamentView user={user} />
          )}
        </Panel>
      </View>
    </Root>
  );
};

export default App;